mapper.insert:
INSERT INTO resumes (
    user_id
    , title
    , template_id
    , created_at
    , updated_at
) VALUES (
    #{userId}
    , #{title}
    , #{templateId}
    , CURRENT_TIMESTAMP
    , CURRENT_TIMESTAMP
)

INSERT INTO resume_profile (
    resume_id
    , name
    , email
    , phone
    , address
    , profile_image
    , birth_date
    , introduction
) VALUES (
    #{resumeId}
    , #{name}
    , #{email}
    , #{phone}
    , #{address}
    , #{profileImage}
    , #{birthDate}
    , #{introduction}
)

INSERT INTO resume_skill (
    resume_id
    , skill_name
    , category
    , proficiency
    , sort_order
    , created_at
    , updated_at
) VALUES (
    #{resumeId}
    , #{skillName}
    , #{category}
    , #{proficiency}
    , #{sortOrder}
    , CURRENT_TIMESTAMP
    , CURRENT_TIMESTAMP
)

INSERT INTO resume_education (
    resume_id
    , school_name
    , major
    , degree
    , start_date
    , end_date
    , description
    , sort_order
    , created_at
    , updated_at
) VALUES (
    #{resumeId}
    , #{schoolName}
    , #{major}
    , #{degree}
    , #{startDate}
    , #{endDate}
    , #{description}
    , #{sortOrder}
    , CURRENT_TIMESTAMP
    , CURRENT_TIMESTAMP
)

INSERT INTO resume_experience (
    resume_id
    , company_name
    , position
    , start_date
    , end_date
    , is_current
    , description
    , sort_order
    , created_at
    , updated_at
) VALUES (
    #{resumeId}
    , #{companyName}
    , #{position}
    , #{startDate}
    , #{endDate}
    , #{isCurrent}
    , #{description}
    , #{sortOrder}
    , CURRENT_TIMESTAMP
    , CURRENT_TIMESTAMP
)
